// Ajv 8.20.0 standalone validator generator.
//
// The generated module is ESM and self-contained: Ajv's runtime helpers are
// inlined so the generated file has no dependency on ajv at runtime beyond the
// ValidateFunction type. Ajv's standalone output is plain JavaScript; the
// emitted .ts file carries @ts-nocheck because the generated code is machine
// shaped, while its exported surface is explicitly typed.

import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import { fail } from "./utils.mjs";

const UCS2LENGTH = `function ucs2length(str) {
  const len = str.length;
  let length = 0;
  let pos = 0;
  let value;
  while (pos < len) {
    length++;
    value = str.charCodeAt(pos++);
    if (value >= 0xd800 && value <= 0xdbff && pos < len) {
      value = str.charCodeAt(pos);
      if ((value & 0xfc00) === 0xdc00) pos++;
    }
  }
  return length;
}`;

const EQUAL = `function equal(a, b) {
  if (a === b) return true;
  if (a && b && typeof a == "object" && typeof b == "object") {
    if (a.constructor !== b.constructor) return false;
    let length, i;
    if (Array.isArray(a)) {
      length = a.length;
      if (length != b.length) return false;
      for (i = length; i-- !== 0; ) if (!equal(a[i], b[i])) return false;
      return true;
    }
    if (a.constructor === RegExp) return a.source === b.source && a.flags === b.flags;
    if (a.valueOf !== Object.prototype.valueOf) return a.valueOf() === b.valueOf();
    if (a.toString !== Object.prototype.toString) return a.toString() === b.toString();
    const keys = Object.keys(a);
    length = keys.length;
    if (length !== Object.keys(b).length) return false;
    for (i = length; i-- !== 0; ) if (!Object.prototype.hasOwnProperty.call(b, keys[i])) return false;
    for (i = length; i-- !== 0; ) {
      const key = keys[i];
      if (!equal(a[key], b[key])) return false;
    }
    return true;
  }
  return a !== a && b !== b;
}`;

export function generateValidatorModule(entry, exportName) {
  const ajv = new Ajv2020({
    allErrors: true,
    strict: true,
    // DD-FND-036 requires unique $id, local $ref and rejection of unknown
    // keywords, but not Ajv's strictRequired check. Keep strictSchema et al.
    // so unknown keywords still fail, while allowing `required` names on
    // objects whose property set is not declared in the schema file (opaque
    // payloads owned by a domain). Ajv still enforces the required keys at
    // validation time.
    strictRequired: false,
    allowUnionTypes: true,
    validateFormats: false,
    keywords: [
      "x-evoplug-ddl",
      "x-evoplug-vocabulary",
      "x-evoplug-deferred-validation",
      "x-evoplug-total-order",
    ],
    code: { source: true, esm: true },
  });
  let validate;
  try {
    validate = ajv.compile(entry.schema);
  } catch (error) {
    fail(`${entry.relative}: Ajv compile failed: ${error.message}`);
  }
  let code;
  try {
    code = standaloneCode(ajv, validate);
  } catch (error) {
    fail(`${entry.relative}: Ajv standalone failed: ${error.message}`);
  }
  const transformed = transformStandalone(code, entry.relative);
  const rootMatch =
    /export const validate = (validate[0-9]+);export default \1;/.exec(code) ??
    /module\.exports = (validate[0-9]+);/.exec(code);
  if (!rootMatch) fail(`${entry.relative}: cannot identify the standalone root validator`);
  const rootFunction = rootMatch[1];
  const header = [
    "// DO NOT EDIT. Generated by tools/schema-codegen/cli.mjs.",
    `// Source: ${entry.relative}`,
    `// source-sha256: ${entry.sourceHash}`,
    `// schema-id: ${entry.schema.$id}`,
    "",
    "/* eslint-disable */",
    "// @ts-nocheck -- Ajv standalone output is machine generated JavaScript.",
    'import type { ValidateFunction } from "ajv";',
    "",
  ].join("\n");
  return `${header}${transformed}\n\nexport const ${exportName}: ValidateFunction = ${rootFunction};\nexport default ${exportName};\n`;
}

function transformStandalone(code, file) {
  let out = code;
  out = out.replace(
    /export const validate = (validate[0-9]+);export default \1;/,
    "",
  );
  out = out.replace(/^"use strict";/, "");
  const runtime = [];
  if (out.includes('require("ajv/dist/runtime/ucs2length").default')) {
    out = out.replaceAll('require("ajv/dist/runtime/ucs2length").default', "ucs2length");
    runtime.push(UCS2LENGTH);
  }
  if (out.includes('require("ajv/dist/runtime/equal").default')) {
    out = out.replaceAll('require("ajv/dist/runtime/equal").default', "equal");
    runtime.push(EQUAL);
  }
  const remaining = out.match(/require\("[^"]+"\)/);
  if (remaining) {
    fail(`${file}: unsupported Ajv runtime helper ${remaining[0]}`);
  }
  if (out.includes("module.exports")) {
    fail(`${file}: Ajv standalone emitted CommonJS despite code.esm`);
  }
  if (!/function validate[0-9]+\(/.test(out)) {
    fail(`${file}: Ajv standalone output has no validator function`);
  }
  return `${runtime.join("\n\n")}\n\n${out.trim()}`;
}
